const look = (n: number) => LOOKS[n - 1];

/** Reading order. Look 1 is the cover and is rendered by the page itself. */
export const ROWS: Row[] = [
  { kind: 'pair', looks: [look(2), look(3)] },
  { kind: 'full', look: look(4) },
  {
    kind: 'statement',
    lines: ['Two pieces.', 'Two colorways.', 'Nothing else.'],
    body: 'One heavyweight fleece, cut boxy and dyed after it is sewn. Worn as a set, or broken apart and mixed.',
  },
  { kind: 'pair', looks: [look(5), look(6)] },
  { kind: 'full', look: look(7) },
  { kind: 'pair', looks: [look(8), look(9)] },
  { kind: 'full', look: look(10) },
];

/** URL value for a colorway, e.g. "Warm Cream" -> "warm-cream". */
export const colorParam = (name: string) => name.toLowerCase().replace(/\s+/g, '-');
